<div class="checkout-layout"><section class="glass p-4"><div class="section-heading"><h2><?= e($order['order_number']) ?></h2><span class="status status-<?= strtolower($order['status']) ?>"><?= e($order['status']) ?></span></div><p><?= e(date('F j, Y · g:i a',strtotime($order['created_at']))) ?></p><?php foreach(all('SELECT * FROM order_items WHERE order_id=?',[$order['id']]) as $oi): ?><div class="summary-row"><div><strong><?= e($oi['product_name']) ?></strong><small class="d-block"><?= e(trim($oi['size'].' '.$oi['color'])) ?> · Qty <?= $oi['quantity'] ?> × <?= money($oi['price']) ?></small></div><strong><?= money((float)$oi['price']*$oi['quantity']) ?></strong></div><?php endforeach; ?><hr><h3>Deliver to</h3><p><?= e($order['full_name']) ?><br><?= e($order['shipping_address']) ?><br><?= e($order['phone']) ?><br><?= e($order['email']) ?></p><h3>Payment</h3><p><?= e(strtoupper($order['payment_method'])) ?> · <?= e($order['payment_status']) ?></p></section><aside class="glass order-summary"><h2>Order total</h2><?php foreach(['subtotal','shipping','discount','total'] as $key): ?><div class="summary-row <?= $key==='total'?'grand-total':'' ?>"><span><?= ucfirst($key) ?></span><strong><?= $key==='discount'?'−':'' ?><?= money($order[$key]) ?></strong></div><?php endforeach; ?></aside></div>
